command:
$ErrorActionPreference='Stop'; $ssh=(Get-Command ssh -ErrorAction Stop).Source; $remote=@'
set -u
cd /home/ubuntu/mei-mg-email
echo CHECK_BRT=$(TZ=America/Sao_Paulo date +%Y-%m-%dT%H:%M:%S%z)
echo RUNTIME_HEAD=$(git rev-parse HEAD 2>/dev/null || true)
echo ORIGIN_MAIN=$(git rev-parse origin/main 2>/dev/null || true)
echo WORKER=$(sudo systemctl is-active mei-mg-email-worker.service 2>/dev/null || true)
echo WORKER_ENABLED=$(sudo systemctl is-enabled mei-mg-email-worker.service 2>/dev/null || true)
echo NDR_GUARD=$(sudo systemctl is-active mei-mg-email-ndr-guard.service 2>/dev/null || true)
echo NDR_GUARD_ENABLED=$(sudo systemctl is-enabled mei-mg-email-ndr-guard.service 2>/dev/null || true)
echo AUTOREPAIR=$(sudo systemctl is-active mei-mg-email-autorepair.timer 2>/dev/null || true)
sudo systemctl show mei-mg-email-worker.service -p Restart -p RestartUSec -p StartLimitIntervalUSec -p ExecStart --no-pager | sed 's/^/SYSTEMD_/'
if sudo test -f /var/lib/mei-mg-email/sender_blocked.pause || test -f runtime/sender_blocked.pause; then echo SENTINEL=present; else echo SENTINEL=absent; fi
echo DB_READY=$(sudo docker exec mei-mg-email-db pg_isready -U postgres -d mei_mg_email 2>/dev/null | grep -c 'accepting connections' || true)
q(){ sudo docker exec mei-mg-email-db psql -U postgres -d mei_mg_email -At -v ON_ERROR_STOP=1 -c "$1"; }
echo SENT24_QUEUE=$(q "select count(*) from mei_email.envios where status::text in ('submitted','enviado','delivered') and enviado_em>=now()-interval '24 hours';")
if [ "$(q "select to_regclass('mei_email.envios_externos_cota') is not null;")" = t ]; then echo SENT24_EXTERNAL=$(q "select count(*) from mei_email.envios_externos_cota where sent_at>=now()-interval '24 hours';"); else echo SENT24_EXTERNAL=0; fi
echo PENDING=$(q "select count(*) from mei_email.envios where status::text in ('pendente','pending','enviando','processing');")
echo SYNTH_OPEN=$(q "select count(*) from mei_email.envios x join mei_email.empresas e on e.cnpj=x.cnpj where x.status::text in ('pendente','pending','enviando','processing') and (btrim(coalesce(e.marketing_autorizado_origem,''))='user_explicit_authorization_2026-08-20' or lower(btrim(coalesce(e.marketing_autorizado_origem,''))) like '%operator_authorization_true%');")
echo REPLAY_OPEN=$(q "select count(*) from mei_email.envios x where x.status::text in ('pendente','pending','enviando','processing') and exists(select 1 from mei_email.envios h where h.id<>x.id and lower(btrim(h.email::text))=lower(btrim(x.email::text)) and h.status::text in ('submitted','enviado','delivered','bounced','bounce_permanent'));")
echo DUP_TERMINAL_EMAILS=$(q "select count(*) from (select lower(btrim(email::text)) e from mei_email.envios where status::text in ('submitted','enviado','delivered') and email is not null group by 1 having count(*)>1) d;")
echo ELIGIBLE_AUTH_POOL=$(q "select count(*) from mei_email.empresas e where e.marketing_autorizado is true and nullif(btrim(coalesce(e.marketing_autorizado_origem,'')),'') is not null and btrim(e.marketing_autorizado_origem) not in ('confirmacao_operador_2026-08-12','confirmacao_operador_2026-08-13','politica_importacao_operador_2026-08-13','user_explicit_authorization_2026-08-20') and lower(btrim(e.marketing_autorizado_origem)) not like '%operator_authorization_true%' and e.mei_verificado is true and nullif(btrim(coalesce(e.mei_verificado_origem,'')),'') is not null and btrim(e.mei_verificado_origem) not in ('override_operador_2026-08-13','politica_importacao_operador_2026-08-13') and e.opt_out=false and e.situacao_cadastral='ATIVA' and upper(e.uf)='MG' and upper(e.tipo_regime)='MEI' and e.provavel_terceiro=false and e.email is not null and mei_email.is_valid_email_address(e.email) and not exists(select 1 from mei_email.email_suppressions s where s.active and ((s.scope='email' and lower(btrim(s.value::text))=lower(btrim(e.email::text))) or (s.scope='cnpj' and regexp_replace(s.value::text,'[^0-9]','','g')=e.cnpj))) and not exists(select 1 from mei_email.envios h where h.cnpj=e.cnpj or lower(btrim(h.email::text))=lower(btrim(e.email::text)));")
echo LONG_DB_SESSIONS=$(q "select count(*) from pg_stat_activity where pid<>pg_backend_pid() and state<>'idle' and query_start is not null and now()-query_start>interval '5 minutes';")
echo ADVISORY_LOCKS=$(q "select count(*) from pg_locks where locktype='advisory';")
fh=$(q "select table_schema from information_schema.tables where table_name='flyway_schema_history' order by (table_schema='public') desc limit 1;")
echo FLYWAY_SCHEMA=${fh:-missing}
if [ -n "$fh" ]; then echo FLYWAY_37_42=$(q "select coalesce(string_agg(version||':'||success::text,',' order by installed_rank),'none') from $fh.flyway_schema_history where version in ('37','38','39','40','42');"); echo FLYWAY_FAILED=$(q "select count(*) from $fh.flyway_schema_history where success=false;"); fi
errs=0; for c in $(sudo docker ps --format '{{.Names}}' | grep -i flyway || true); do n=$(sudo docker logs --tail 120 "$c" 2>&1 | grep -Eic 'status_lote|operator does not exist|enum.*cast|cannot cast' || true); errs=$((errs+n)); done; echo FLYWAY_ENUM_CAST_ERRORS=$errs
echo NDR_MAILBOX_WIDE=$(grep -c 'graph.microsoft.com/v1.0/users/{quote(provider.address)}/messages?' scripts/ndr_guard.py 2>/dev/null || true)
.venv/bin/python - <<'PY'
try:
 from app.email_provider import MicrosoftGraphEmailProvider
 p=MicrosoftGraphEmailProvider(); p._get_access_token(); print('GRAPH_AUTH=ok')
except Exception as exc:
 print('GRAPH_AUTH=failed:'+type(exc).__name__)
PY
if getent hosts graph.microsoft.com >/dev/null 2>&1; then echo DNS_GRAPH=ok; else echo DNS_GRAPH=failed; fi
echo LATEST=$(q "select coalesce(max(enviado_em)::text,'none') from mei_email.envios where status::text in ('submitted','enviado','delivered');")
echo AS42004_LAST30M=$(sudo journalctl -u mei-mg-email-worker.service --since '-30 minutes' --no-pager | grep -Eic 'AS\(42004\)|bad outbound sender|5\.1\.8' || true)
'@; $out=& $ssh -o BatchMode=yes -o ConnectTimeout=15 shopvivaliz-vm $remote 2>$null; $out | ForEach-Object {Write-Output $_}; if($LASTEXITCODE -ne 0){throw 'live sender audit failed'}
